create or replace view public.published_products as select id,name,price_cop,original_price_cop,category,room,images,badge,description,stock,type,customer_shipping_cop,shipping_estimate_city,shipping_checked_at,(source in ('aliexpress_ds','cjdropshipping')) as shipping_quote_required from public.catalog_products where status='published' and (source not in ('aliexpress_ds','cjdropshipping') or (customer_shipping_cop is not null and customer_shipping_cop>=0 and shipping_estimate_city is not null and btrim(shipping_estimate_city)<>'' and shipping_checked_at is not null)); grant select on public.published_products to anon,authenticated;
